package com.bank.qa.api;

import java.util.Map;

// A simplified REST response: status, headers, JSON-like body, timing.
class ApiResponse {
    final int status;
    final Map<String, String> headers;
    final Map<String, Object> body;   // field -> typed value
    final long elapsedMs;
    ApiResponse(int status, Map<String, String> headers, Map<String, Object> body, long elapsedMs) {
        this.status = status; this.headers = headers; this.body = body; this.elapsedMs = elapsedMs;
    }
}
