package com.bank.qa.api;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Asserts the FULL response contract, not just the status code.
class ResponseValidator {
    private static final Logger log = Logger.getLogger(ResponseValidator.class.getName());
    private int passed = 0, total = 0;

    private void assertTrue(String name, boolean cond) {
        total++;
        if (cond) { passed++; log.info("PASS " + name); }
        else log.severe("FAIL " + name);
    }

    // Positive: validate a successful created response end to end.
    void validateSuccess(ApiResponse r, long slaMs) {
        assertTrue("status is 201", r.status == 201);
        assertTrue("content-type json", "application/json".equals(r.headers.get("Content-Type")));
        assertTrue("correlation id header present", r.headers.containsKey("X-Correlation-Id"));
        // Required fields + types (schema-like)
        assertTrue("has transactionId", r.body.get("transactionId") instanceof String);
        assertTrue("amount is numeric", r.body.get("amount") instanceof BigDecimal);
        assertTrue("has status field", "COMPLETED".equals(r.body.get("status")));
        // No sensitive leak
        assertTrue("no internal/sensitive fields leaked",
            !r.body.containsKey("passwordHash") && !r.body.containsKey("internalId"));
        // SLA
        assertTrue("within SLA (" + slaMs + "ms)", r.elapsedMs <= slaMs);
    }

    // Negative: validate an error response is correct and safe.
    void validateError(ApiResponse r, int expectedStatus, String expectedCode) {
        assertTrue("status is " + expectedStatus, r.status == expectedStatus);
        assertTrue("has errorCode " + expectedCode, expectedCode.equals(r.body.get("errorCode")));
        Object msg = r.body.get("message");
        assertTrue("message is safe (no stack/SQL)",
            msg instanceof String && !((String) msg).toLowerCase().contains("exception")
                && !((String) msg).toLowerCase().contains("select "));
    }

    void summary() { log.info("Validation: " + passed + "/" + total + " assertions passed"); }
}
