package com.bank.qa.api;

import java.math.BigDecimal;
import java.util.logging.*;

public class ApiValidationDemo {
    private static final Logger log = Logger.getLogger(ApiValidationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new ApiLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        TransferApi api = new TransferApi();
        ResponseValidator v = new ResponseValidator();

        log.info("=== POSITIVE: valid authorized transfer ===");
        v.validateSuccess(api.transfer("user", "SAV2001", new BigDecimal("50000")), 200);

        log.info("=== NEGATIVE: unauthenticated ===");
        v.validateError(api.transfer(null, "SAV2001", new BigDecimal("50000")), 401, "AUTH_REQUIRED");

        log.info("=== NEGATIVE: forbidden token ===");
        v.validateError(api.transfer("guest", "SAV2001", new BigDecimal("50000")), 403, "FORBIDDEN");

        log.info("=== NEGATIVE: invalid amount ===");
        v.validateError(api.transfer("user", "SAV2001", new BigDecimal("-1")), 400, "INVALID_AMOUNT");

        log.info("=== NEGATIVE: business rule (overdraft) ===");
        v.validateError(api.transfer("user", "SAV2001", new BigDecimal("9999999")), 400, "INSUFFICIENT_FUNDS");

        v.summary();
    }
}

